mapper.select:
SELECT id, practice_session_id, user_id, event_type, card_id, analysis_id, outcome,
       user_utterance, reason, note_text, status_before, status_after, created_at
FROM voice_practice_event
WHERE practice_session_id = #{practiceSessionId}
  AND user_id = #{userId}
ORDER BY id ASC
LIMIT #{limit}

SELECT COUNT(1)
FROM voice_practice_event
WHERE practice_session_id = #{practiceSessionId}
  AND user_id = #{userId}
  AND card_id = #{cardId}
  AND event_type = 'attempt'
  AND status_after IS NOT NULL
  AND status_after != ''
